import{_ as e,o as t,c as a,Q as s}from"./chunks/framework.b67c47e6.js";const f=JSON.parse('{"title":"BTLx Designs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/btlx_designs/index.md","filePath":"guide/management/btlx_designs/index.md","lastUpdated":1793787262000}'),n={name:"guide/management/btlx_designs/index.md"},i=s('<h1 id="btlx-designs" tabindex="-1">BTLx Designs <a class="header-anchor" href="#btlx-designs" aria-label="Permalink to &quot;BTLx Designs&quot;">​</a></h1><p>A panel can be built from a <strong>BTLx file</strong> instead of an IFC. You upload the BTLx where you would upload the panel&#39;s IFC, and Produuz.it creates the design, its revisions and its units from it, exactly as it does for an IFC.</p><div class="info custom-block"><p class="custom-block-title">Feature flag</p><p>BTLx designs must be switched on for your company by a Produuz.it administrator. Until then, the upload dialog does not offer <code>.btlx</code> for the panel models, and a BTLx uploaded there is refused.</p></div><nav class="table-of-contents"><ul><li><a href="#which-btlx-files-can-be-a-design">Which BTLx files can be a design</a></li><li><a href="#uploading-a-btlx">Uploading a BTLx</a></li><li><a href="#what-the-analysis-gives-you">What the analysis gives you</a></li><li><a href="#what-works-with-a-btlx-design">What works with a BTLx design</a></li></ul></nav><h2 id="which-btlx-files-can-be-a-design" tabindex="-1">Which BTLx files can be a design <a class="header-anchor" href="#which-btlx-files-can-be-a-design" aria-label="Permalink to &quot;Which BTLx files can be a design&quot;">​</a></h2><p>A BTLx can be the model of a design when it describes <strong>one panel and places every part in it</strong>: each part carries its position in the panel. This is what CAD programs export for a prefabricated wall or floor element, and it is what the <a href="/guide/management/tools/">Mobfile Generator</a> already reads.</p><p>Two kinds of BTLx files cannot be a design:</p><ul><li><strong>Part lists.</strong> A list of parts to cut, with no position in the panel, describes no panel. The analysis stops and the design shows the reason: how many parts have no position.</li><li><strong>Files with several panels.</strong> One file is one design. Export one BTLx per panel.</li></ul><h2 id="uploading-a-btlx" tabindex="-1">Uploading a BTLx <a class="header-anchor" href="#uploading-a-btlx" aria-label="Permalink to &quot;Uploading a BTLx&quot;">​</a></h2><ol><li>In the project <strong>Files</strong>, click <strong>Upload</strong> and pick <strong>Assembly BTLx</strong> as the file category. It only accepts <code>.btlx</code> files, and IFCs stay in <strong>Assembly IFCs</strong>.</li><li>Drop the <code>.btlx</code> files. Name each file after its panel, as you would an IFC: <code>W001.btlx</code> creates or updates the design <strong>W001</strong>.</li><li>Run <strong>Generate designs</strong> as usual.</li></ol><p>The design is analysed like an IFC panel, with the project&#39;s <a href="/guide/management/ifcps/">IFC Parsing Setup</a>: its rules are matched on the BTLx attributes of each part (see <a href="/guide/management/ifcps/#btlx-files">BTLx files</a>, where a starter setup can be downloaded).</p><p><strong>One model per design.</strong> A design is built from one IFC <strong>or</strong> one BTLx, never both. Uploading a BTLx for a design that already has an IFC (or the other way round) is refused, and the message names the file already there. Delete that file first if the design should now come from the other one.</p><p><strong>Exporting again.</strong> Uploading the same panel exported again, with only a new export date, is recognised as the same file: it creates no new revision and does not analyse the panel again. A panel that changed creates a new revision, as with an IFC.</p><h2 id="what-the-analysis-gives-you" tabindex="-1">What the analysis gives you <a class="header-anchor" href="#what-the-analysis-gives-you" aria-label="Permalink to &quot;What the analysis gives you&quot;">​</a></h2><ul><li><strong>Parts.</strong> One part per placed instance in the file, identified by its BTLx GUID, so a part keeps its identity, its status and its batch when the panel is exported again, as long as your CAD program keeps the GUIDs. Each gets its category, branch, zone, reference, name, material and size, and reaches the parts list, part batches, logistics and the checklists.</li><li><strong>The panel.</strong> Its length, height and thickness, and its gross and net areas, for planning and the production Excel. A BTLx carries no window elements, so openings are not counted.</li><li><strong>References.</strong> As for IFC: from the reference property of your setup, or by shape. Two parts with the same blank and the same processings get the same reference.</li><li><strong>A 3D model.</strong> The viewer shows the panel and lets you pick its parts, with the zones of the viewer BOM. See <a href="/guide/viewer/#designs-built-from-a-btlx-file">Designs built from a BTLx file</a>.</li><li><strong>Not created:</strong> part drawings, and subassemblies (a BTLx design is one panel).</li></ul><h2 id="what-works-with-a-btlx-design" tabindex="-1">What works with a BTLx design <a class="header-anchor" href="#what-works-with-a-btlx-design" aria-label="Permalink to &quot;What works with a BTLx design&quot;">​</a></h2><table><thead><tr><th>Works</th><th>Not available</th></tr></thead><tbody><tr><td>Designs, revisions, quantities and units</td><td>Bills of Materials (PDF) and the custom CSVs</td></tr><tr><td>Parts list, part batches, logistics, checklists and planning</td><td>Part drawings</td></tr><tr><td>MOB v1, MOB v2 and AUTO MOB v2 machine files, from reports and from automations</td><td>Automatic drawings</td></tr><tr><td>Production and worktime Excel, QR and rack load stickers, issues and quality control reports</td><td>Wood and plate machine files (BTL, BTLx, BVX, XCS, Ardis, DXF, CIX, …), steel and roof files</td></tr><tr><td>The 3D viewer: model, zones, part selection</td><td>Measurement and clipping in the 3D viewer</td></tr><tr><td></td><td>Multipanel groups</td></tr></tbody></table><p>What is not available says so instead of failing:</p><ul><li>In the <strong>report form</strong>, report types that cannot use the selected BTLx units are disabled, and a warning names how many units are concerned.</li><li>A report started anyway (from a template or the API) fails with a message listing the BTLx designs to take out.</li><li><strong>Automatic drawings</strong> are skipped for a BTLx design, also when an automation launches them after the analysis; the design&#39;s drawing card shows why.</li><li>A BTLx design cannot join a <strong>multipanel group</strong>: the group dialog disables it.</li><li>In the <strong>3D viewer</strong>, measurement and the clipping plane are not offered.</li></ul>',19),o=[i];function r(l,d,h,g,c,p){return t(),a("div",null,o)}const m=e(n,[["render",r]]);export{f as __pageData,m as default};
